function x({registerIndicator:y,sourceValues:h,nulls:b}){y({id:"oa-cfo",name:"Chande Forecast Oscillator",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"cfo",type:"line",title:"CFO",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero Line",color:"#787b86",dashed:!0}],calc(s,a){const e=Math.max(1,Math.min(5e3,Math.floor(Number(a.period)||14))),N=h(s,a.source??"close"),u=new Array(s.length).fill(NaN),f=new Array(e).fill(NaN);let r=0,n=0,o=0,l=0;const c=e*(e-1)/2,F=e*(e-1)*(2*e-1)/6,p=e*F-c*c;for(let i=0;i<s.length;i++){const t=N[i];if(!Number.isFinite(t))continue;const d=f[n];if(Number.isFinite(d)?(o-=d,l-=o,l+=(e-1)*t):(l+=r*t,r+=1),o+=t,f[n]=t,n=(n+1)%e,r<e||p===0)continue;const m=(e*l-c*o)/p,X=(o-m*c)/e+m*(e-1);t!==0&&(u[i]=100*(t-X)/t)}return{cfo:b(u)}}})}export{x as default};
